import random,statistics
from collections import defaultdict
def trial(seed,nrel=12000,ns=300,nr=500,na=150,q=2000):
 r=random.Random(seed); rel=set()
 while len(rel)<nrel: rel.add((r.randrange(ns),r.randrange(nr),r.randrange(na)))
 sr=defaultdict(set); ar=defaultdict(set); ex=defaultdict(set)
 rel=list(rel)
 for s,x,a in rel: sr[s].add(x); ar[a].add(x); ex[(s,a)].add(x)
 ps=[]
 for s,x,a in r.sample(rel,min(q,len(rel))):
  c=sr[s]&ar[a]; t=ex[(s,a)]
  if c: ps.append(len(c&t)/len(c))
 return statistics.mean(ps)
vals=[trial(i) for i in range(8)]
print('mean_pairwise_precision',statistics.mean(vals))
print('relation_instance_precision',1.0)
